const getIconPath = (name, colorClass) => {
  let color = null;
  if (name === 'GetAllSvg') {
    return svgMap;
  }
  if (Array.isArray(colorClass)) {
    color = colorClass.map((item) => (item ? (colorMap[item] || item) : null));
  } else {
    color = colorClass ? (colorMap[colorClass] || colorClass) : null;
  }
  if (svgMap[name] && color) {
    return svgMap[name](color);
  }
  return '';
};

export default getIconPath;
